import { apiClient, unwrap, type BffResponse } from '../api';

export interface ArapTtAllocationFilter {
  ngayCt1: string;
  ngayCt2: string;
  tk: string;
  maKh?: string;
  sttRec?: string;
}

export interface ArapTtSourceItem {
  sttRec: string;
  maCt: string;
  ngayCt: string;
  soCt: string;
  tk: string;
  maKh: string;
  tenKh: string;
  tien: number;
  tienNt: number;
  daPb: number;
  daPbNt: number;
  tt: number;
  ttNt: number;
  cl: number;
  clNt: number;
}

export interface ArapTtTargetItem {
  sttRec: string;
  maCt: string;
  ngayCt: string;
  soCt: string;
  tk: string;
  maKh?: string;
  tenKh?: string;
  tien: number;
  tienNt: number;
  daPb: number;
  daPbNt: number;
  tt: number;
  ttNt: number;
  cl: number;
  clNt: number;
  voucher: number;
}

export interface ArapTtAllocationQueryResult {
  loaiPb: number;
  sourceItems: ArapTtSourceItem[];
  targetItems: ArapTtTargetItem[];
  allocatedCount?: number;
}

function queryParams(filter: ArapTtAllocationFilter): Record<string, string> {
  const params: Record<string, string> = {
    ngayCt1: filter.ngayCt1,
    ngayCt2: filter.ngayCt2,
    tk: filter.tk,
  };
  const maKh = filter.maKh?.trim();
  const sttRec = filter.sttRec?.trim();
  if (maKh) params.maKh = maKh;
  if (sttRec) params.sttRec = sttRec;
  return params;
}

function filterBody(filter: ArapTtAllocationFilter): ArapTtAllocationFilter {
  const body: ArapTtAllocationFilter = {
    ngayCt1: filter.ngayCt1,
    ngayCt2: filter.ngayCt2,
    tk: filter.tk.trim(),
  };
  const maKh = filter.maKh?.trim();
  const sttRec = filter.sttRec?.trim();
  if (maKh) body.maKh = maKh;
  if (sttRec) body.sttRec = sttRec;
  return body;
}

export async function queryArapTtAllocations(
  filter: ArapTtAllocationFilter,
): Promise<ArapTtAllocationQueryResult> {
  const qs = new URLSearchParams(queryParams(filter)).toString();
  const path = qs
    ? `/accounting/arap-tt-allocations?${qs}`
    : '/accounting/arap-tt-allocations';
  const res = await apiClient.get<BffResponse<ArapTtAllocationQueryResult>>(path);
  return unwrap(res);
}

export interface ArapTtAutoBody extends ArapTtAllocationFilter {
  sourceSttRec: string;
  loai: 1 | 2;
}

export async function previewArapTtAuto(body: ArapTtAutoBody): Promise<ArapTtAllocationQueryResult> {
  const res = await apiClient.post<BffResponse<ArapTtAllocationQueryResult>>(
    '/accounting/arap-tt-allocations/auto',
    {
      ...filterBody(body),
      sourceSttRec: body.sourceSttRec,
      loai: body.loai,
    },
  );
  return unwrap(res);
}

export interface ArapTtAllocateTarget {
  sttRec: string;
  tt: number;
  ttNt: number;
  ngayCt?: string;
}

export interface ArapTtAllocateBody extends ArapTtAllocationFilter {
  sourceSttRec: string;
  lanPb: number;
  targets: ArapTtAllocateTarget[];
}

export async function allocateArapTt(body: ArapTtAllocateBody): Promise<ArapTtAllocationQueryResult> {
  const res = await apiClient.post<BffResponse<ArapTtAllocationQueryResult>>(
    '/accounting/arap-tt-allocations/allocate',
    {
      ...filterBody(body),
      sourceSttRec: body.sourceSttRec,
      lanPb: body.lanPb,
      targets: body.targets,
    },
  );
  return unwrap(res);
}

export interface ArapTtDeleteBody extends ArapTtAllocationFilter {
  sttRecNo: string;
  sttRecCo: string;
  tk: string;
  maKh: string;
  maNt?: string;
}

export async function deleteArapTt(body: ArapTtDeleteBody): Promise<ArapTtAllocationQueryResult> {
  const res = await apiClient.post<BffResponse<ArapTtAllocationQueryResult>>(
    '/accounting/arap-tt-allocations/delete',
    {
      ...filterBody(body),
      sttRecNo: body.sttRecNo,
      sttRecCo: body.sttRecCo,
      tk: body.tk,
      maKh: body.maKh,
      ...(body.maNt?.trim() ? { maNt: body.maNt.trim() } : {}),
    },
  );
  return unwrap(res);
}
